def solution(rows, key):
    """
    Groups a list of dicts by the value of a specific key.
    Returns a dict mapping value -> list of rows in original order.
    """
    grouped = defaultdict(list)
    for row in rows:
        if key in row:
            grouped[row[key]].append(row)
    return dict(grouped)

def solution(nums, k):
