from collections import OrderedDict

def solution(capacity, ops):
    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == 'get':
            key = op[1]
            if key not in cache:
                results.append(-1)
            else:
                cache.move_to_end(key)
                results.append(cache[key])
        elif op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)

    return results

from collections import deque

def solution(grid, start, end):
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    sr, sc = start
    er, ec = end

    if not (0 <= sr < rows and 0 <= sc < cols) or not (0 <= er < rows and 0 <= ec < cols):
        return -1

    if grid[sr][sc] == 1 or grid[er][ec] == 1:
        return -1

    if start == end:
        return 0

    queue = deque([(sr, sc, 0)])
    visited = {(sr, sc)}

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == (er, ec):
            return dist

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1

def solution(expr):
    tokens = expr.split()
    if not tokens:
        return 0

    # First pass: multiplication and division
    numbers = []
    operators = []

    i = 0
    while i < len(tokens):
        if tokens[i] in ('+', '-'):
            operators.append(tokens[i])
            i += 1
        elif tokens[i] in ('*', '/'):
            op = tokens[i]
            prev = int(numbers.pop())
            nxt = int(tokens[i+1])
            if op == '*':
                res = prev * nxt
            else:
                # Truncate toward zero
                res = int(float(prev) / nxt)
            numbers.append(str(res))
            i += 2
        else:
            numbers.append(tokens[i])
            i += 1

    # Second pass: addition and subtraction
    total = int(numbers[0])
    for idx, op in enumerate(operators):
        nxt = int(numbers[idx + 1])
        if op == '+':
            total += nxt
        else:
            total -= nxt

    return total
